public class Driver {static class Buffer{Integer value; synchronized void put(int n)throws InterruptedException{while(value!=null)wait();value=n;System.out.println("Produced: "+n);notifyAll();}synchronized int take()throws InterruptedException{while(value==null)wait();int n=value;value=null;System.out.println("Consumed: "+n);notifyAll();return n;}}public static void main(String[]a)throws Exception{Buffer b=new Buffer();Thread p=new Thread(()->{try{for(int i=1;i<=3;i++)b.put(i*10);}catch(InterruptedException e){}}),c=new Thread(()->{try{for(int i=0;i<3;i++)b.take();}catch(InterruptedException e){}});p.start();c.start();p.join();c.join();}}
